-- Hojuelas colombianas: publicación transaccional en siete idiomas.
-- Ejecutar una sola vez DESPUÉS de comprobar por HTTP 200 y hash exacto los 12 WebP desplegados.
DO $hojuelas$
DECLARE
 j constant jsonb := $records$[{"language":"es","slug":"hojuelas-colombianas","public_path":"/hojuelas-colombianas","title":"Hojuelas colombianas: receta crujiente con canela y azúcar","excerpt":"Hojuelas colombianas tradicionales: masa fina de harina y mantequilla, frita hasta quedar crocante y terminada con canela y azúcar. Rinde 20 unidades.","summary":"Las hojuelas u hojaldras colombianas son láminas delgadas de masa frita que se sirven especialmente en Navidad con natilla y buñuelos. En esta versión, la mantequilla se integra con harina y azúcar, el agua une la masa y un reposo de 30 minutos permite estirarla a 1–2 mm; después se fríe a 170–175 °C y se termina con canela y azúcar.","notes":"La masa debe quedar elástica sin ser pegajosa; añade el agua poco a poco y solo una pizca adicional de harina si es necesario. Mantén el aceite entre 170 y 175 °C y fríe tandas pequeñas, sin tapar la olla ni dejar el aceite solo. La masa fina es esencial: gruesa queda correosa. Si prefieres sabor cítrico, reemplaza parte del agua por jugo de naranja. Enfría sobre rejilla y guarda herméticamente hasta 2–3 días. Contiene trigo y leche. La información nutricional es una estimación: el aceite realmente absorbido varía.","ingredients":[{"group":"Para la masa","name":"harina de trigo de todo uso","amount":"250","unit":"g"},{"group":"Para la masa","name":"azúcar blanca","amount":"20","unit":"g"},{"group":"Para la masa","name":"mantequilla sin sal a temperatura ambiente","amount":"25","unit":"g"},{"group":"Para la masa","name":"sal fina","amount":"2","unit":"g"},{"group":"Para la masa","name":"agua a temperatura ambiente","amount":"115","unit":"ml"},{"group":"Para freír","name":"aceite vegetal de sabor neutro","amount":"700","unit":"ml"},{"group":"Para terminar","name":"azúcar blanca fina","amount":"30","unit":"g"},{"group":"Para terminar","name":"canela molida","amount":"2","unit":"g"}],"steps":[{"title":"Mezcla los ingredientes secos","content":"En un bol amplio, mezcla 250 g de harina de trigo con 20 g de azúcar y 2 g de sal hasta distribuirlos de forma uniforme.","image_alt":"Bol de cerámica con harina de trigo, montículos de azúcar y sal, y cuchara de madera; mezcla seca sin hojuelas fritas.","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Forma la masa","content":"Agrega 25 g de mantequilla blanda y 115 ml de agua poco a poco a los secos; mezcla hasta formar una masa unida, sin harina suelta.","image_alt":"Bol con harina parcialmente hidratada y mantequilla, jarrita vertiendo agua sobre masa cruda, sin hojuelas fritas.","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Amasa","content":"Pasa la masa a la mesa y amásala durante 5 minutos hasta que resulte lisa, homogénea y no pegajosa; evita añadir harina de más.","image_alt":"Bola de masa cruda lisa en tabla de madera y manos amasando; ninguna hojuela frita","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Deja reposar","content":"Cubre la masa y déjala reposar 30 minutos a temperatura ambiente para que se pueda estirar sin encogerse.","image_alt":"Bola de masa cruda descansando bajo paño de algodón en un bol sobre mesa; ninguna hojuela frita","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Estira la masa","content":"Con un rodillo extiende la masa en tandas hasta que tenga 1–2 mm de grosor, casi translúcida, sobre una mesa ligeramente enharinada.","image_alt":"Lámina fina de masa cruda extendida con rodillo y mesa enharinada, textura casi translúcida; ninguna hojuela frita","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Corta las hojuelas","content":"Corta la lámina en aproximadamente 20 rectángulos de 10 × 6 cm o rombos similares; mantenlos separados para que no se peguen.","image_alt":"Rectángulos y rombos planos de masa cruda cortados con rueda de pasta sobre superficie enharinada; ninguna hojuela frita","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Fríe por tandas","content":"Calienta el aceite a 170–175 °C y fríe pocas piezas a la vez durante unos 30–45 segundos por lado, hasta que se hinchen y doren; retíralas y deja que escurran sobre rejilla.","image_alt":"Olla honda con aceite burbujeante y láminas de masa inflándose y dorándose, espumadera visible, cocina realista sin texto","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Espolvorea canela y azúcar","content":"Mezcla 30 g de azúcar con 2 g de canela y espolvorea las hojuelas ya escurridas mientras están tibias. Sírvelas crujientes.","image_alt":"Plato cerámico claro con 20 hojuelas colombianas doradas, delgadas y burbujeantes, espolvoreadas con azúcar y canela; comida terminada, foto portada","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Postres","course":"Postre","cuisine":"Colombiana","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Plato cerámico claro con 20 hojuelas colombianas doradas, delgadas y burbujeantes, espolvoreadas con azúcar y canela; comida terminada, foto portada"}],"video_urls":[],"keywords":["hojuelas colombianas","receta de hojuelas","hojaldras colombianas","hojuelas de Navidad","hojuelas con canela y azúcar","cómo hacer hojuelas crujientes"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 hojuela (1/20 de la receta)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"El aceite absorbido no está medido: 30 g es una hipótesis de cálculo y modifica las calorías y grasas; sodio incluye los 2g de sal","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Hojuelas colombianas crujientes con canela y azúcar | Manual de Cocina","description":"Prepara hojuelas colombianas doradas y crujientes, con masa fina de mantequilla y canela con azúcar. 8 pasos ilustrados, 20 unidades y consejos.","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"¿Por qué las hojuelas quedan blandas en lugar de crujientes?","a":"Lo más común es que la masa quede demasiado gruesa o el aceite esté frío. Estírala a 1–2 mm y mantén el aceite cerca de 170–175 °C para obtener burbujas y una textura crocante."},{"q":"¿Se pueden hacer hojuelas sin huevo?","a":"Sí. Esta versión colombiana usa harina, mantequilla y agua, como una de las variantes caseras tradicionales. No necesita huevo para quedar crujiente si la masa está fina."},{"q":"¿Se puede reemplazar el agua por jugo de naranja?","a":"Sí. Sustituye parte o toda el agua por zumo de naranja sin pulpa; el sabor será más cítrico. Agrégalo gradualmente porque la absorción varía según la harina."},{"q":"¿Cómo saber si el aceite tiene la temperatura correcta?","a":"Lo más preciso es un termómetro de cocina a 170–175 °C. Sin él, una tira pequeña de masa debe burbujear enseguida y subir sin ennegrecerse de inmediato."},{"q":"¿Cómo se conservan las hojuelas crujientes?","a":"Déjalas enfriar por completo sobre rejilla y guárdalas en un recipiente hermético a temperatura ambiente durante 2–3 días, lejos de la humedad. No conviene refrigerarlas."}],"image_alt":"Plato cerámico claro con 20 hojuelas colombianas doradas, delgadas y burbujeantes, espolvoreadas con azúcar y canela; comida terminada, foto portada"},"published":true,"editorial_status":"published","content_html":"<p>Las hojuelas u hojaldras colombianas son láminas delgadas de masa frita que se sirven especialmente en Navidad con natilla y buñuelos. En esta versión, la mantequilla se integra con harina y azúcar, el agua une la masa y un reposo de 30 minutos permite estirarla a 1–2 mm; después se fríe a 170–175 °C y se termina con canela y azúcar.</p><p>La masa debe quedar elástica sin ser pegajosa; añade el agua poco a poco y solo una pizca adicional de harina si es necesario. Mantén el aceite entre 170 y 175 °C y fríe tandas pequeñas, sin tapar la olla ni dejar el aceite solo. La masa fina es esencial: gruesa queda correosa. Si prefieres sabor cítrico, reemplaza parte del agua por jugo de naranja. Enfría sobre rejilla y guarda herméticamente hasta 2–3 días. Contiene trigo y leche. La información nutricional es una estimación: el aceite realmente absorbido varía.</p>","id":"0b4a2d6d-fec2-584a-82ca-6b4322b72bd2","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"de","slug":"kolumbianische-hojuelas","public_path":"/de/kolumbianische-hojuelas","title":"Kolumbianische Hojuelas: knusprig mit Zimtzucker","excerpt":"Dünne kolumbianische Teigblätter, knusprig ausgebacken und mit Zimtzucker bestreut. Ergibt 20 Stück.","summary":"Hojuelas, auch Hojaldras genannt, sind dünne frittierte Teigblätter, die in Kolumbien besonders zur Weihnachtszeit mit Natilla und Buñuelos serviert werden. Dieser eifreie Teig wird 30 Minuten entspannt, auf 1–2 mm ausgerollt und bei 170–175 °C ausgebacken.","notes":"Wasser nach und nach zugeben; der Teig soll elastisch, aber nicht klebrig sein. Das Öl konstant bei 170–175 °C halten und nur kleine Portionen frittieren. Enthält Weizen und Milch. Vollständig auf einem Gitter auskühlen lassen und luftdicht 2–3 Tage bei Raumtemperatur lagern. Die Nährwerte sind geschätzt, weil die tatsächliche Ölaufnahme schwankt.","ingredients":[{"group":"Für den Teig","name":"Weizenmehl Type 405","amount":"250","unit":"g"},{"group":"Für den Teig","name":"weißer Zucker","amount":"20","unit":"g"},{"group":"Für den Teig","name":"weiche ungesalzene Butter","amount":"25","unit":"g"},{"group":"Für den Teig","name":"feines Salz","amount":"2","unit":"g"},{"group":"Für den Teig","name":"Wasser bei Raumtemperatur","amount":"115","unit":"ml"},{"group":"Zum Frittieren","name":"neutrales Pflanzenöl","amount":"700","unit":"ml"},{"group":"Zum Bestreuen","name":"feiner weißer Zucker","amount":"30","unit":"g"},{"group":"Zum Bestreuen","name":"gemahlener Zimt","amount":"2","unit":"g"}],"steps":[{"title":"Trockene Zutaten mischen","content":"250 g Mehl mit 20 g Zucker und 2 g Salz in einer großen Schüssel gleichmäßig vermischen.","image_alt":"Schüssel mit Mehl, Zucker und Salz","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Teig zusammenfügen","content":"25 g weiche Butter und nach und nach 115 ml Wasser zugeben; mischen, bis ein zusammenhängender Teig ohne loses Mehl entsteht.","image_alt":"Wasser wird zu Mehl und Butter für rohen Teig gegossen","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Teig kneten","content":"Den Teig auf der Arbeitsfläche 5 Minuten kneten, bis er glatt, gleichmäßig und nicht klebrig ist; möglichst kein zusätzliches Mehl einarbeiten.","image_alt":"Hände kneten einen rohen Teig auf Holz","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Teig ruhen lassen","content":"Den Teig abdecken und 30 Minuten bei Raumtemperatur ruhen lassen, damit er sich ohne Zurückspringen ausrollen lässt.","image_alt":"Roher Teig ruht abgedeckt in einer Schüssel","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Teig dünn ausrollen","content":"Den Teig portionsweise auf leicht bemehlter Fläche auf 1–2 mm, fast durchscheinend, ausrollen.","image_alt":"Roher Teig wird hauchdünn ausgerollt","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Hojuelas schneiden","content":"Die Teigplatte in etwa 20 Rechtecke von 10 × 6 cm oder ähnlich große Rauten schneiden und getrennt ablegen.","image_alt":"Rohe Teigrechtecke werden mit einem Teigrad geschnitten","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Portionsweise frittieren","content":"Öl auf 170–175 °C erhitzen. Wenige Stücke gleichzeitig etwa 30–45 Sekunden je Seite frittieren, bis sie Blasen bilden und goldgelb sind; auf einem Gitter abtropfen lassen.","image_alt":"Teigblätter blubbern beim Frittieren im heißen Öl","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Mit Zimtzucker bestreuen","content":"30 g Zucker mit 2 g Zimt mischen und auf die noch warmen, abgetropften Hojuelas streuen. Knusprig servieren.","image_alt":"Goldene kolumbianische Hojuelas mit Zimtzucker","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Desserts","course":"Dessert","cuisine":"Kolumbianisch","difficulty":"Einfach","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Goldene kolumbianische Hojuelas mit Zimtzucker"}],"video_urls":[],"keywords":["kolumbianische Hojuelas","Hojaldras","Zimtzucker","kolumbianisches Weihnachtsgebäck","frittierter Teig"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 Hojuela (1/20 des Rezepts)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"Die Nährwerte sind geschätzt, weil die tatsächliche Ölaufnahme schwankt.","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Kolumbianische Hojuelas mit Zimtzucker | Manual de Cocina","description":"Knusprige kolumbianische Hojuelas in 8 bebilderten Schritten: dünner Butterteig, 170–175 °C Frittieröl und Zimtzucker. Ergibt 20 Stück.","image_alt":"Goldene kolumbianische Hojuelas mit Zimtzucker","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"Warum werden die Hojuelas weich?","a":"Meist ist der Teig zu dick oder das Öl zu kalt. Auf 1–2 mm ausrollen und 170–175 °C halten."},{"q":"Geht das Rezept ohne Ei?","a":"Ja. Diese kolumbianische Variante besteht aus Mehl, Butter und Wasser und wird bei dünnem Ausrollen trotzdem knusprig."},{"q":"Kann Wasser durch Orangensaft ersetzt werden?","a":"Ja, ganz oder teilweise durch Saft ohne Fruchtfleisch. Wegen unterschiedlicher Mehlaufnahme langsam zugeben."},{"q":"Wie prüfe ich die Öltemperatur?","a":"Am zuverlässigsten mit einem Thermometer. Bei 170–175 °C blubbert ein Teststreifen sofort, ohne rasch dunkel zu werden."},{"q":"Wie bleiben Hojuelas knusprig?","a":"Vollständig auf einem Gitter auskühlen und luftdicht 2–3 Tage trocken bei Raumtemperatur lagern; nicht kühlen."}]},"published":true,"editorial_status":"published","content_html":"<p>Hojuelas, auch Hojaldras genannt, sind dünne frittierte Teigblätter, die in Kolumbien besonders zur Weihnachtszeit mit Natilla und Buñuelos serviert werden. Dieser eifreie Teig wird 30 Minuten entspannt, auf 1–2 mm ausgerollt und bei 170–175 °C ausgebacken.</p><p>Wasser nach und nach zugeben; der Teig soll elastisch, aber nicht klebrig sein. Das Öl konstant bei 170–175 °C halten und nur kleine Portionen frittieren. Enthält Weizen und Milch. Vollständig auf einem Gitter auskühlen lassen und luftdicht 2–3 Tage bei Raumtemperatur lagern. Die Nährwerte sind geschätzt, weil die tatsächliche Ölaufnahme schwankt.</p>","id":"bcb9c826-4c92-5a9c-8c00-055d8030408a","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"en","slug":"colombian-hojuelas","public_path":"/en/colombian-hojuelas","title":"Colombian hojuelas: crisp cinnamon-sugar pastries","excerpt":"Thin Colombian dough sheets fried until crisp and finished with cinnamon sugar. Makes 20 pieces.","summary":"Hojuelas, also called hojaldras, are thin sheets of fried dough served in Colombia especially at Christmas with natilla and buñuelos. This egg-free dough rests for 30 minutes, is rolled to 1–2 mm, fried at 170–175°C and dusted with cinnamon sugar.","notes":"Add the water gradually: the dough should be elastic but not sticky. Keep the oil at 170–175°C and fry small batches. Contains wheat and milk. Cool completely on a rack and store airtight at room temperature for 2–3 days. Nutrition is estimated because actual oil absorption varies.","ingredients":[{"group":"For the dough","name":"all-purpose wheat flour","amount":"250","unit":"g"},{"group":"For the dough","name":"white sugar","amount":"20","unit":"g"},{"group":"For the dough","name":"softened unsalted butter","amount":"25","unit":"g"},{"group":"For the dough","name":"fine salt","amount":"2","unit":"g"},{"group":"For the dough","name":"room-temperature water","amount":"115","unit":"ml"},{"group":"For frying","name":"neutral vegetable oil","amount":"700","unit":"ml"},{"group":"To finish","name":"fine white sugar","amount":"30","unit":"g"},{"group":"To finish","name":"ground cinnamon","amount":"2","unit":"g"}],"steps":[{"title":"Mix the dry ingredients","content":"Mix 250 g flour with 20 g sugar and 2 g salt in a large bowl until evenly distributed.","image_alt":"Bowl with flour, sugar and salt","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Bring the dough together","content":"Add 25 g softened butter and gradually add 115 ml water; mix until a cohesive dough forms with no loose flour.","image_alt":"Water poured into flour and butter to form raw dough","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Knead the dough","content":"Knead on the worktop for 5 minutes until smooth, even and no longer sticky; avoid adding extra flour.","image_alt":"Hands kneading raw dough on a wooden board","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Rest the dough","content":"Cover and rest the dough for 30 minutes at room temperature so it can be rolled without springing back.","image_alt":"Raw dough resting under a cloth in a bowl","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Roll the dough thin","content":"Roll the dough in batches on a lightly floured surface to 1–2 mm thick, almost translucent.","image_alt":"Raw dough rolled into a very thin sheet","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Cut the hojuelas","content":"Cut into about 20 rectangles measuring 10 × 6 cm or similar diamonds, keeping the pieces separate.","image_alt":"Raw dough rectangles cut with a pastry wheel","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Fry in batches","content":"Heat the oil to 170–175°C. Fry only a few pieces at a time for 30–45 seconds per side until blistered and golden; drain on a rack.","image_alt":"Thin dough bubbling in hot oil during frying","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Dust with cinnamon sugar","content":"Mix 30 g sugar with 2 g cinnamon and dust the drained hojuelas while warm. Serve crisp.","image_alt":"Golden Colombian hojuelas dusted with cinnamon sugar","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Desserts","course":"Dessert","cuisine":"Colombian","difficulty":"Easy","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Golden Colombian hojuelas dusted with cinnamon sugar"}],"video_urls":[],"keywords":["Colombian hojuelas","hojaldras","cinnamon sugar","Colombian Christmas dessert","fried dough"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 hojuela (1/20 of the recipe)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"Nutrition is estimated because actual oil absorption varies.","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Colombian hojuelas with cinnamon sugar | Manual de Cocina","description":"Make crisp Colombian hojuelas in 8 illustrated steps: thin butter dough, 170–175°C frying oil and cinnamon sugar. Yields 20 pieces.","image_alt":"Golden Colombian hojuelas dusted with cinnamon sugar","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"Why are my hojuelas soft instead of crisp?","a":"The dough is usually too thick or the oil too cool. Roll to 1–2 mm and keep the oil at 170–175°C."},{"q":"Can Colombian hojuelas be made without egg?","a":"Yes. This version uses flour, butter and water and becomes crisp when rolled very thin."},{"q":"Can I replace the water with orange juice?","a":"Yes, replace some or all with pulp-free juice, adding it gradually because flour absorption varies."},{"q":"How do I know the oil is hot enough?","a":"A thermometer is best. At 170–175°C a small dough strip should bubble immediately without turning dark at once."},{"q":"How should I store crisp hojuelas?","a":"Cool completely on a rack, then keep airtight at room temperature away from humidity for 2–3 days; do not refrigerate."}]},"published":true,"editorial_status":"published","content_html":"<p>Hojuelas, also called hojaldras, are thin sheets of fried dough served in Colombia especially at Christmas with natilla and buñuelos. This egg-free dough rests for 30 minutes, is rolled to 1–2 mm, fried at 170–175°C and dusted with cinnamon sugar.</p><p>Add the water gradually: the dough should be elastic but not sticky. Keep the oil at 170–175°C and fry small batches. Contains wheat and milk. Cool completely on a rack and store airtight at room temperature for 2–3 days. Nutrition is estimated because actual oil absorption varies.</p>","id":"784ae434-b1ec-544a-945d-048b4366cdf9","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"fr","slug":"hojuelas-colombiennes","public_path":"/fr/hojuelas-colombiennes","title":"Hojuelas colombiennes croustillantes au sucre cannelle","excerpt":"Fines feuilles de pâte colombiennes frites jusqu’à devenir croustillantes, puis poudrées de sucre à la cannelle. Pour 20 pièces.","summary":"Les hojuelas, ou hojaldras, sont de fines feuilles de pâte frite servies en Colombie, surtout à Noël avec la natilla et les buñuelos. Cette pâte sans œuf repose 30 minutes, s’abaisse à 1–2 mm puis se frit à 170–175 °C.","notes":"Ajoutez l’eau progressivement : la pâte doit être souple sans coller. Maintenez l’huile à 170–175 °C et travaillez par petites fournées. Contient blé et lait. Laissez refroidir sur grille et conservez 2–3 jours dans une boîte hermétique à température ambiante. La nutrition reste estimative car l’absorption d’huile varie.","ingredients":[{"group":"Pour la pâte","name":"farine de blé tout usage","amount":"250","unit":"g"},{"group":"Pour la pâte","name":"sucre blanc","amount":"20","unit":"g"},{"group":"Pour la pâte","name":"beurre doux ramolli","amount":"25","unit":"g"},{"group":"Pour la pâte","name":"sel fin","amount":"2","unit":"g"},{"group":"Pour la pâte","name":"eau à température ambiante","amount":"115","unit":"ml"},{"group":"Pour la friture","name":"huile végétale neutre","amount":"700","unit":"ml"},{"group":"Pour la finition","name":"sucre blanc fin","amount":"30","unit":"g"},{"group":"Pour la finition","name":"cannelle moulue","amount":"2","unit":"g"}],"steps":[{"title":"Mélanger les ingrédients secs","content":"Mélangez uniformément 250 g de farine, 20 g de sucre et 2 g de sel dans un grand saladier.","image_alt":"Saladier contenant farine, sucre et sel","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Former la pâte","content":"Ajoutez 25 g de beurre mou puis 115 ml d’eau progressivement; mélangez jusqu’à obtenir une pâte liée sans farine libre.","image_alt":"Eau versée sur farine et beurre pour former une pâte crue","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Pétrir la pâte","content":"Pétrissez 5 minutes sur le plan de travail jusqu’à ce que la pâte soit lisse, homogène et non collante, sans excès de farine.","image_alt":"Mains pétrissant une pâte crue sur bois","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Laisser reposer","content":"Couvrez la pâte et laissez-la reposer 30 minutes à température ambiante afin qu’elle s’étale sans se rétracter.","image_alt":"Pâte crue reposant sous un torchon dans un bol","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Abaisser finement","content":"Abaissez la pâte par portions à 1–2 mm, presque translucide, sur un plan légèrement fariné.","image_alt":"Pâte crue abaissée en feuille très fine","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Découper les hojuelas","content":"Découpez environ 20 rectangles de 10 × 6 cm ou des losanges similaires et gardez-les séparés.","image_alt":"Rectangles de pâte crue découpés à la roulette","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Frire par petites fournées","content":"Chauffez l’huile à 170–175 °C. Faites frire quelques pièces 30–45 secondes par face jusqu’à ce qu’elles cloquent et dorent; égouttez sur grille.","image_alt":"Pâte fine bouillonnant dans l’huile chaude","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Saupoudrer de sucre cannelle","content":"Mélangez 30 g de sucre et 2 g de cannelle, puis poudrez les hojuelas égouttées encore tièdes. Servez croustillant.","image_alt":"Hojuelas colombiennes dorées au sucre cannelle","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Desserts","course":"Dessert","cuisine":"Colombienne","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Hojuelas colombiennes dorées au sucre cannelle"}],"video_urls":[],"keywords":["hojuelas colombiennes","hojaldras","sucre cannelle","dessert de Noël colombien","pâte frite"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 hojuela (1/20 de la recette)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"La nutrition reste estimative car l’absorption d’huile varie.","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Hojuelas colombiennes au sucre cannelle | Manual de Cocina","description":"Hojuelas colombiennes croustillantes en 8 étapes illustrées : pâte fine au beurre, huile à 170–175 °C et sucre cannelle. Pour 20 pièces.","image_alt":"Hojuelas colombiennes dorées au sucre cannelle","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"Pourquoi mes hojuelas ramollissent-elles ?","a":"La pâte est souvent trop épaisse ou l’huile trop froide. Abaissez à 1–2 mm et maintenez 170–175 °C."},{"q":"Peut-on préparer les hojuelas sans œuf ?","a":"Oui. Cette variante utilise farine, beurre et eau et croustille si la pâte est très fine."},{"q":"Puis-je remplacer l’eau par du jus d’orange ?","a":"Oui, en partie ou totalement avec un jus sans pulpe, ajouté progressivement selon l’absorption de la farine."},{"q":"Comment contrôler la température de l’huile ?","a":"Le thermomètre est le plus précis. À 170–175 °C, une bande de pâte bouillonne immédiatement sans noircir."},{"q":"Comment conserver leur croustillant ?","a":"Laissez refroidir sur grille puis gardez 2–3 jours dans une boîte hermétique, au sec et à température ambiante; ne réfrigérez pas."}]},"published":true,"editorial_status":"published","content_html":"<p>Les hojuelas, ou hojaldras, sont de fines feuilles de pâte frite servies en Colombie, surtout à Noël avec la natilla et les buñuelos. Cette pâte sans œuf repose 30 minutes, s’abaisse à 1–2 mm puis se frit à 170–175 °C.</p><p>Ajoutez l’eau progressivement : la pâte doit être souple sans coller. Maintenez l’huile à 170–175 °C et travaillez par petites fournées. Contient blé et lait. Laissez refroidir sur grille et conservez 2–3 jours dans une boîte hermétique à température ambiante. La nutrition reste estimative car l’absorption d’huile varie.</p>","id":"c092357d-d76c-59f7-b66b-789154d692ae","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"it","slug":"hojuelas-colombiane","public_path":"/it/hojuelas-colombiane","title":"Hojuelas colombiane croccanti con zucchero e cannella","excerpt":"Sfoglie sottili colombiane fritte fino a diventare croccanti e rifinite con zucchero alla cannella. Per 20 pezzi.","summary":"Le hojuelas, dette anche hojaldras, sono sottili sfoglie di pasta fritta servite in Colombia soprattutto a Natale con natilla e buñuelos. Questo impasto senza uova riposa 30 minuti, si stende a 1–2 mm e si frigge a 170–175 °C.","notes":"Aggiungete l’acqua poco alla volta: l’impasto deve essere elastico ma non appiccicoso. Mantenete l’olio a 170–175 °C e friggete poche sfoglie per volta. Contiene grano e latte. Raffreddate su griglia e conservate ermeticamente 2–3 giorni a temperatura ambiente. I valori nutrizionali sono stimati perché l’assorbimento d’olio varia.","ingredients":[{"group":"Per l’impasto","name":"farina di grano tenero per tutti gli usi","amount":"250","unit":"g"},{"group":"Per l’impasto","name":"zucchero bianco","amount":"20","unit":"g"},{"group":"Per l’impasto","name":"burro non salato morbido","amount":"25","unit":"g"},{"group":"Per l’impasto","name":"sale fino","amount":"2","unit":"g"},{"group":"Per l’impasto","name":"acqua a temperatura ambiente","amount":"115","unit":"ml"},{"group":"Per friggere","name":"olio vegetale neutro","amount":"700","unit":"ml"},{"group":"Per completare","name":"zucchero bianco fine","amount":"30","unit":"g"},{"group":"Per completare","name":"cannella in polvere","amount":"2","unit":"g"}],"steps":[{"title":"Mescola gli ingredienti secchi","content":"Mescola uniformemente in una ciotola grande 250 g di farina, 20 g di zucchero e 2 g di sale.","image_alt":"Ciotola con farina, zucchero e sale","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Forma l’impasto","content":"Aggiungi 25 g di burro morbido e 115 ml di acqua poco alla volta; mescola fino a ottenere un impasto unito senza farina libera.","image_alt":"Acqua versata su farina e burro per formare impasto crudo","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Impasta","content":"Impasta sul piano per 5 minuti finché risulta liscio, uniforme e non appiccicoso; evita altra farina.","image_alt":"Mani che impastano pasta cruda sul legno","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Lascia riposare","content":"Copri l’impasto e lascialo riposare 30 minuti a temperatura ambiente perché si stenda senza ritirarsi.","image_alt":"Impasto crudo che riposa coperto in ciotola","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Stendi sottile","content":"Stendi l’impasto in porzioni fino a 1–2 mm, quasi traslucido, su un piano leggermente infarinato.","image_alt":"Impasto crudo steso in sfoglia sottilissima","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Taglia le hojuelas","content":"Taglia circa 20 rettangoli da 10 × 6 cm o rombi simili e tienili separati.","image_alt":"Rettangoli di impasto crudo tagliati con rotella","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Friggi in piccole quantità","content":"Scalda l’olio a 170–175 °C. Friggi pochi pezzi per 30–45 secondi per lato finché si gonfiano e dorano; scola su una griglia.","image_alt":"Sfoglie che friggono con bolle nell’olio caldo","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Spolvera con zucchero e cannella","content":"Mescola 30 g di zucchero e 2 g di cannella e spolvera le hojuelas scolate ancora tiepide. Servile croccanti.","image_alt":"Hojuelas colombiane dorate con zucchero e cannella","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Dolci","course":"Dessert","cuisine":"Colombiana","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Hojuelas colombiane dorate con zucchero e cannella"}],"video_urls":[],"keywords":["hojuelas colombiane","hojaldras","zucchero e cannella","dolce natalizio colombiano","pasta fritta"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 hojuela (1/20 della ricetta)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"I valori nutrizionali sono stimati perché l’assorbimento d’olio varia.","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Hojuelas colombiane con zucchero e cannella | Manual de Cocina","description":"Hojuelas colombiane croccanti in 8 passaggi illustrati: impasto sottile al burro, olio a 170–175 °C e zucchero alla cannella. 20 pezzi.","image_alt":"Hojuelas colombiane dorate con zucchero e cannella","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"Perché le hojuelas risultano morbide?","a":"Di solito l’impasto è troppo spesso o l’olio troppo freddo. Stendete a 1–2 mm e mantenete 170–175 °C."},{"q":"Si possono fare senza uova?","a":"Sì. Questa variante usa farina, burro e acqua e diventa croccante se stesa molto sottile."},{"q":"Posso sostituire l’acqua con succo d’arancia?","a":"Sì, in parte o del tutto con succo senza polpa, aggiunto gradualmente perché la farina assorbe in modo variabile."},{"q":"Come verifico la temperatura dell’olio?","a":"Il termometro è più preciso. A 170–175 °C una striscia di prova produce subito bolle senza scurire."},{"q":"Come mantengo le hojuelas croccanti?","a":"Raffreddatele del tutto su griglia e conservatele ermeticamente 2–3 giorni al riparo dall’umidità; non refrigerate."}]},"published":true,"editorial_status":"published","content_html":"<p>Le hojuelas, dette anche hojaldras, sono sottili sfoglie di pasta fritta servite in Colombia soprattutto a Natale con natilla e buñuelos. Questo impasto senza uova riposa 30 minuti, si stende a 1–2 mm e si frigge a 170–175 °C.</p><p>Aggiungete l’acqua poco alla volta: l’impasto deve essere elastico ma non appiccicoso. Mantenete l’olio a 170–175 °C e friggete poche sfoglie per volta. Contiene grano e latte. Raffreddate su griglia e conservate ermeticamente 2–3 giorni a temperatura ambiente. I valori nutrizionali sono stimati perché l’assorbimento d’olio varia.</p>","id":"9decf884-f4c1-5c7c-8cc0-3addc91e3b3f","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"ja","slug":"コロンビアのホフエラス","public_path":"/ja/コロンビアのホフエラス","title":"コロンビアのホフエラス：シナモンシュガーの薄焼き菓子","excerpt":"薄くのばした生地を香ばしく揚げ、シナモンシュガーをまぶすコロンビア菓子。20枚分です。","summary":"ホフエラス（ホハルドラス）は、コロンビアで特にクリスマスにナティージャやブニュエロと一緒に食べる薄い揚げ生地です。卵を使わない生地を30分休ませ、1〜2 mmにのばして170〜175°Cで揚げます。","notes":"水は少しずつ加え、生地は弾力がありながらべたつかない状態にします。油温を170〜175°Cに保ち、少量ずつ揚げます。小麦と乳を含みます。網で完全に冷まして密閉し、室温で2〜3日保存できます。実際の吸油量が変わるため栄養値は推定です。","ingredients":[{"group":"生地","name":"薄力粉または中力粉","amount":"250","unit":"g"},{"group":"生地","name":"白砂糖","amount":"20","unit":"g"},{"group":"生地","name":"室温に戻した無塩バター","amount":"25","unit":"g"},{"group":"生地","name":"細塩","amount":"2","unit":"g"},{"group":"生地","name":"室温の水","amount":"115","unit":"ml"},{"group":"揚げ油","name":"香りの弱い植物油","amount":"700","unit":"ml"},{"group":"仕上げ","name":"細目の白砂糖","amount":"30","unit":"g"},{"group":"仕上げ","name":"シナモンパウダー","amount":"2","unit":"g"}],"steps":[{"title":"粉類を混ぜる","content":"大きなボウルで小麦粉250 g、砂糖20 g、塩2 gを均一に混ぜます。","image_alt":"ボウルに入れた小麦粉、砂糖、塩","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"生地をまとめる","content":"柔らかいバター25 gと水115 mlを少しずつ加え、粉が残らないひとまとまりの生地にします。","image_alt":"小麦粉とバターに水を注いで生の生地を作る様子","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"こねる","content":"台に移して5分こね、なめらかで均一、べたつかない状態にします。余分な粉は加えません。","image_alt":"木の台で生地をこねる手","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"休ませる","content":"生地を覆い、室温で30分休ませて、のばしたときに縮みにくくします。","image_alt":"布をかけてボウルで休ませる生地","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"薄くのばす","content":"軽く打ち粉をした台で、生地を分けながら厚さ1〜2 mm、ほぼ透ける薄さにのばします。","image_alt":"極薄にのばした生の生地","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"切り分ける","content":"約10 × 6 cmの長方形または同程度のひし形を約20枚切り、重ならないように置きます。","image_alt":"パイカッターで切る生の長方形生地","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"少量ずつ揚げる","content":"油を170〜175°Cに熱し、少量ずつ片面30〜45秒を目安に泡が出てきつね色になるまで揚げ、網で油を切ります。","image_alt":"熱い油で泡を立てて揚がる薄い生地","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"シナモンシュガーをまぶす","content":"砂糖30 gとシナモン2 gを混ぜ、油を切った温かいホフエラスにまぶします。カリッとしたうちに供します。","image_alt":"シナモンシュガーをまぶした黄金色のホフエラス","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"デザート","course":"デザート","cuisine":"コロンビア料理","difficulty":"簡単","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"シナモンシュガーをまぶした黄金色のホフエラス"}],"video_urls":[],"keywords":["コロンビアのホフエラス","ホハルドラス","シナモンシュガー","コロンビアのクリスマス菓子","揚げ生地"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1枚（全20枚の1/20）","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"水は少しずつ加え、生地は弾力がありながらべたつかない状態にします。油温を170〜175°Cに保ち、少量ずつ揚げます。小麦と乳を含みます。網で完全に冷まして密閉し、室温で2〜3日保存できます。実際の吸油量が変わるため栄養値は推定です。","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"コロンビアのホフエラス：シナモンシュガー | Manual de Cocina","description":"薄いバター生地を170〜175°Cで揚げるコロンビアのホフエラス。写真付き8工程、シナモンシュガー仕上げ、20枚分。","image_alt":"シナモンシュガーをまぶした黄金色のホフエラス","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"ホフエラスが柔らかくなるのはなぜですか？","a":"生地が厚すぎるか油温が低いことが主因です。1〜2 mmにのばし、170〜175°Cを保ちます。"},{"q":"卵なしでも作れますか？","a":"はい。この配合は小麦粉、バター、水を使い、薄くのばすことでカリッと仕上がります。"},{"q":"水をオレンジジュースに替えられますか？","a":"果肉のないジュースで一部または全部を代用できます。粉の吸水が変わるため少しずつ加えます。"},{"q":"油温はどう確認しますか？","a":"温度計が最も確実です。170〜175°Cなら小さな試し生地がすぐ泡立ち、急に黒くなりません。"},{"q":"カリッと保存する方法は？","a":"網で完全に冷まし、湿気を避けて密閉し、室温で2〜3日保存します。冷蔵は避けます。"}]},"published":true,"editorial_status":"published","content_html":"<p>ホフエラス（ホハルドラス）は、コロンビアで特にクリスマスにナティージャやブニュエロと一緒に食べる薄い揚げ生地です。卵を使わない生地を30分休ませ、1〜2 mmにのばして170〜175°Cで揚げます。</p><p>水は少しずつ加え、生地は弾力がありながらべたつかない状態にします。油温を170〜175°Cに保ち、少量ずつ揚げます。小麦と乳を含みます。網で完全に冷まして密閉し、室温で2〜3日保存できます。実際の吸油量が変わるため栄養値は推定です。</p>","id":"5795c6ec-8bdb-59be-b08d-4caa29924b8e","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0},{"language":"pt","slug":"hojuelas-colombianas-receita","public_path":"/pt/hojuelas-colombianas-receita","title":"Hojuelas colombianas crocantes com açúcar e canela","excerpt":"Lâminas finas de massa colombiana fritas até ficarem crocantes e finalizadas com açúcar e canela. Rende 20 unidades.","summary":"As hojuelas, também chamadas hojaldras, são lâminas finas de massa frita servidas na Colômbia, especialmente no Natal com natilla e buñuelos. Esta massa sem ovo descansa 30 minutos, é aberta a 1–2 mm e frita a 170–175°C.","notes":"Adicione a água aos poucos: a massa deve ficar elástica sem grudar. Mantenha o óleo a 170–175°C e frite poucas unidades por vez. Contém trigo e leite. Esfrie em grade e guarde hermeticamente por 2–3 dias em temperatura ambiente. A nutrição é estimada porque a absorção real de óleo varia.","ingredients":[{"group":"Para a massa","name":"farinha de trigo de uso geral","amount":"250","unit":"g"},{"group":"Para a massa","name":"açúcar branco","amount":"20","unit":"g"},{"group":"Para a massa","name":"manteiga sem sal amolecida","amount":"25","unit":"g"},{"group":"Para a massa","name":"sal fino","amount":"2","unit":"g"},{"group":"Para a massa","name":"água em temperatura ambiente","amount":"115","unit":"ml"},{"group":"Para fritar","name":"óleo vegetal neutro","amount":"700","unit":"ml"},{"group":"Para finalizar","name":"açúcar branco fino","amount":"30","unit":"g"},{"group":"Para finalizar","name":"canela em pó","amount":"2","unit":"g"}],"steps":[{"title":"Misture os secos","content":"Misture uniformemente 250 g de farinha, 20 g de açúcar e 2 g de sal em uma tigela grande.","image_alt":"Tigela com farinha, açúcar e sal","image_url":"/recetas/hojuelas-colombianas/paso-01.webp"},{"title":"Forme a massa","content":"Junte 25 g de manteiga macia e 115 ml de água aos poucos; misture até formar massa unida, sem farinha solta.","image_alt":"Água derramada sobre farinha e manteiga para formar massa crua","image_url":"/recetas/hojuelas-colombianas/paso-02.webp"},{"title":"Sove a massa","content":"Sove na bancada por 5 minutos até ficar lisa, uniforme e sem grudar; evite acrescentar farinha.","image_alt":"Mãos sovando massa crua em tábua de madeira","image_url":"/recetas/hojuelas-colombianas/paso-03.webp"},{"title":"Deixe descansar","content":"Cubra a massa e deixe descansar 30 minutos em temperatura ambiente para abrir sem encolher.","image_alt":"Massa crua descansando sob pano em tigela","image_url":"/recetas/hojuelas-colombianas/paso-04.webp"},{"title":"Abra bem fino","content":"Abra a massa em porções sobre bancada levemente enfarinhada até 1–2 mm, quase translúcida.","image_alt":"Massa crua aberta em lâmina muito fina","image_url":"/recetas/hojuelas-colombianas/paso-05.webp"},{"title":"Corte as hojuelas","content":"Corte cerca de 20 retângulos de 10 × 6 cm ou losangos semelhantes e mantenha separados.","image_alt":"Retângulos de massa crua cortados com carretilha","image_url":"/recetas/hojuelas-colombianas/paso-06.webp"},{"title":"Frite em porções","content":"Aqueça o óleo a 170–175°C. Frite poucas peças por 30–45 segundos de cada lado, até criar bolhas e dourar; escorra em grade.","image_alt":"Massa fina borbulhando no óleo quente","image_url":"/recetas/hojuelas-colombianas/paso-07.webp"},{"title":"Polvilhe açúcar e canela","content":"Misture 30 g de açúcar com 2 g de canela e polvilhe as hojuelas escorridas ainda mornas. Sirva crocante.","image_alt":"Hojuelas colombianas douradas com açúcar e canela","image_url":"/recetas/hojuelas-colombianas/paso-08.webp"}],"category":"Sobremesas","course":"Sobremesa","cuisine":"Colombiana","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":70,"rest_time_minutes":30,"servings":20,"image_url":"/recetas/hojuelas-colombianas/portada.webp","gallery":[{"url":"/recetas/hojuelas-colombianas/portada.webp","alt":"Hojuelas colombianas douradas com açúcar e canela"}],"video_urls":[],"keywords":["hojuelas colombianas","hojaldras","açúcar e canela","doce natalino colombiano","massa frita"],"nutrition":{"calories":78,"protein_g":1.3,"carbs_g":12.1,"fat_g":2.6,"saturated_fat_g":0.8,"fiber_g":0.4,"sugar_g":2.5,"sodium_mg":40,"estimated":true,"serving_size":"1 hojuela (1/20 da receita)","source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/","method":"Cálculo por peso inicial más 30g estimados de aceite retenido; datos por 100g por alimento; dividido entre 20","note":"A nutrição é estimada porque a absorção real de óleo varia.","inputs":[{"fdc_id":"168936","name":"Flour, wheat, white, all-purpose, enriched, unbleached","grams":250,"per100":{"calories":364,"protein_g":10.33,"carbs_g":76.31,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2},"source":"https://whatyoueat.io/foods/168936-enriched-unbleached-all-purpose-white-wheat-flour"},{"fdc_id":"173430","name":"Butter, without salt","grams":25,"per100":{"calories":717,"protein_g":0.85,"carbs_g":0.06,"fat_g":81.11,"saturated_fat_g":50.5,"fiber_g":0,"sugar_g":0.06,"sodium_mg":11},"source":"https://fdc.nal.usda.gov/food-details/173430/nutrients"},{"fdc_id":"169655","name":"Sugars, granulated","grams":50,"per100":{"calories":387,"protein_g":0,"carbs_g":100,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sugar_g":100,"sodium_mg":1},"source":"https://fdc.nal.usda.gov/food-search/?query=sugars%20granulated"},{"fdc_id":null,"name":"Ground cinnamon (USDA reference approximation)","grams":2,"per100":{"calories":247,"protein_g":4,"carbs_g":81,"fat_g":1.24,"saturated_fat_g":0.345,"fiber_g":53,"sugar_g":2.2,"sodium_mg":10},"source":"https://fdc.nal.usda.gov/food-search/?query=cinnamon%20ground"},{"fdc_id":null,"name":"Vegetable oil retained after frying (assumed, not 700 ml bath)","grams":30,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":7.4,"fiber_g":0,"sugar_g":0,"sodium_mg":0},"source":"https://fdc.nal.usda.gov/food-search/?query=oil%20canola"}]},"seo":{"title":"Hojuelas colombianas com açúcar e canela | Manual de Cocina","description":"Hojuelas colombianas crocantes em 8 etapas ilustradas: massa fina com manteiga, óleo a 170–175°C e açúcar com canela. Rende 20.","image_alt":"Hojuelas colombianas douradas com açúcar e canela","image_variants":["/recetas/hojuelas-colombianas/portada-1x1.webp","/recetas/hojuelas-colombianas/portada-4x3.webp","/recetas/hojuelas-colombianas/portada-16x9.webp"],"faq":[{"q":"Por que as hojuelas ficam moles?","a":"Normalmente a massa está grossa ou o óleo frio. Abra a 1–2 mm e mantenha 170–175°C."},{"q":"É possível fazer sem ovo?","a":"Sim. Esta versão leva farinha, manteiga e água e fica crocante quando a massa é bem fina."},{"q":"Posso trocar a água por suco de laranja?","a":"Sim, em parte ou por completo com suco sem polpa, adicionado aos poucos porque a farinha absorve de modo variável."},{"q":"Como saber se o óleo está na temperatura certa?","a":"O termômetro é mais preciso. A 170–175°C, uma tira pequena borbulha imediatamente sem escurecer depressa."},{"q":"Como conservar as hojuelas crocantes?","a":"Esfrie totalmente em grade e guarde em pote hermético, longe da umidade, por 2–3 dias em temperatura ambiente; não refrigere."}]},"published":true,"editorial_status":"published","content_html":"<p>As hojuelas, também chamadas hojaldras, são lâminas finas de massa frita servidas na Colômbia, especialmente no Natal com natilla e buñuelos. Esta massa sem ovo descansa 30 minutos, é aberta a 1–2 mm e frita a 170–175°C.</p><p>Adicione a água aos poucos: a massa deve ficar elástica sem grudar. Mantenha o óleo a 170–175°C e frite poucas unidades por vez. Contém trigo e leite. Esfrie em grade e guarde hermeticamente por 2–3 dias em temperatura ambiente. A nutrição é estimada porque a absorção real de óleo varia.</p>","id":"cae05d4b-ecce-5ea2-beb4-07b3739d1c9f","recipe_group_id":"2ee52a3f-1824-5ed2-9e69-a390c120f096","source_url":null,"source_post_id":null,"published_at":"2026-10-11T05:30:00+00:00","ready_at":"2026-10-11T05:30:00+00:00","rating_count":0,"rating_sum":0}]$records$::jsonb;
 g constant uuid := '2ee52a3f-1824-5ed2-9e69-a390c120f096';
 n int;
BEGIN
 IF jsonb_array_length(j)<>7
   OR (SELECT count(DISTINCT x->>'language') FROM jsonb_array_elements(j) x)<>7
   OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j) x)<>7
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(j) x WHERE jsonb_array_length(x->'steps')<>8)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(j) x WHERE jsonb_array_length(x->'seo'->'faq')<>5)
 THEN RAISE EXCEPTION 'Invalid Hojuelas 7-language payload'; END IF;

 IF EXISTS(SELECT 1 FROM public.recipes WHERE recipe_group_id=g) THEN
   IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
      AND (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g AND published)=7 THEN
     RAISE NOTICE 'Hojuelas group already published 7/7; no mutation';
     RETURN;
   END IF;
   RAISE EXCEPTION 'Hojuelas group exists in divergent state';
 END IF;

 IF EXISTS(
   SELECT 1 FROM public.recipes r
   JOIN jsonb_array_elements(j) x
     ON (r.language=x->>'language' AND r.slug=x->>'slug')
     OR r.public_path=x->>'public_path'
 ) THEN RAISE EXCEPTION 'Recipe slug or public_path collision'; END IF;

 IF EXISTS(
   SELECT 1 FROM public.content_pages p
   JOIN jsonb_array_elements(j) x ON p.public_path=x->>'public_path'
 ) THEN RAISE EXCEPTION 'content_pages public_path collision'; END IF;

 IF EXISTS(
   SELECT 1 FROM public.content_redirects r
   JOIN jsonb_array_elements(j) x ON r.source_path=x->>'public_path'
 ) THEN RAISE EXCEPTION 'content_redirects source_path collision'; END IF;

 INSERT INTO public.recipes (
   id,recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,
   prep_time_minutes,cook_time_minutes,servings,image_url,published,published_at,
   content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,
   nutrition,gallery,video_urls,seo,source_post_id,source_url,public_path,
   editorial_status,ready_at,rating_count,rating_sum
 )
 SELECT id,recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,
   prep_time_minutes,cook_time_minutes,servings,image_url,published,published_at,
   content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,
   nutrition,gallery,video_urls,seo,source_post_id,source_url,public_path,
   editorial_status,ready_at,rating_count,rating_sum
 FROM jsonb_populate_recordset(NULL::public.recipes,j);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>7 THEN RAISE EXCEPTION 'Expected 7 inserts, got %',n; END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g AND published)<>7
 THEN RAISE EXCEPTION 'Postcondition failed: group not published 7/7'; END IF;
END $hojuelas$;
